class Solution {
    public String predictPartyVictory(String senate) {
        int n = senate.length();
        java.util.Queue<Integer> radiant = new java.util.ArrayDeque<>();
        java.util.Queue<Integer> dire = new java.util.ArrayDeque<>();

        for (int i = 0; i < n; i++) {
            if (senate.charAt(i) == 'R') {
                radiant.offer(i);
            } else {
                dire.offer(i);
            }
        }

        while (!radiant.isEmpty() && !dire.isEmpty()) {
            int rIndex = radiant.poll();
            int dIndex = dire.poll();
            if (rIndex < dIndex) {
                radiant.offer(rIndex + n);
            } else {
                dire.offer(dIndex + n);
            }
        }

        return radiant.isEmpty() ? "Dire" : "Radiant";
    }
}

class Solution {
    public String predictPartyVictory(String senate) {
        java.util.Queue<Character> queue = new java.util.ArrayDeque<>();
        int radiant = 0;
        int dire = 0;

        for (char senator : senate.toCharArray()) {
            queue.offer(senator);
            if (senator == 'R') {
                radiant++;
            } else {
                dire++;
            }
        }

        int banRadiant = 0;
        int banDire = 0;
        while (radiant > 0 && dire > 0) {
            char senator = queue.poll();
            if (senator == 'R') {
                if (banRadiant > 0) {
                    banRadiant--;
                    radiant--;
                } else {
                    banDire++;
                    queue.offer('R');
                }
            } else {
                if (banDire > 0) {
                    banDire--;
                    dire--;
                } else {
                    banRadiant++;
                    queue.offer('D');
                }
            }
        }

        return radiant > 0 ? "Radiant" : "Dire";
    }
}

class Solution {
    public String predictPartyVictory(String senate) {
        int n = senate.length();
        boolean[] removed = new boolean[n];
        int radiantCount = 0;
        int direCount = 0;
        for (int i = 0; i < n; i++) {
            if (senate.charAt(i) == 'R') {
                radiantCount++;
            } else {
                direCount++;
            }
        }

        int pendingRadiantBans = 0;
        int pendingDireBans = 0;
        while (radiantCount > 0 && direCount > 0) {
            for (int i = 0; i < n; i++) {
                if (removed[i]) {
                    continue;
                }
                if (senate.charAt(i) == 'R') {
                    if (pendingRadiantBans > 0) {
                        pendingRadiantBans--;
                        removed[i] = true;
                        radiantCount--;
                    } else {
                        pendingDireBans++;
                    }
                } else {
                    if (pendingDireBans > 0) {
                        pendingDireBans--;
                        removed[i] = true;
                        direCount--;
                    } else {
                        pendingRadiantBans++;
                    }
                }
            }
        }

        return radiantCount > 0 ? "Radiant" : "Dire";
    }
}

class Solution {
    public String predictPartyVictory(String senate) {
        int banRadiant = 0;
        int banDire = 0;

        while (true) {
            int keptRadiant = 0;
            int keptDire = 0;
            StringBuilder nextRound = new StringBuilder();

            for (int i = 0; i < senate.length(); i++) {
                char senator = senate.charAt(i);
                if (senator == 'R') {
                    if (banRadiant > 0) {
                        banRadiant--;
                    } else {
                        banDire++;
                        nextRound.append('R');
                        keptRadiant++;
                    }
                } else {
                    if (banDire > 0) {
                        banDire--;
                    } else {
                        banRadiant++;
                        nextRound.append('D');
                        keptDire++;
                    }
                }
            }

            if (keptRadiant == 0) {
                return "Dire";
            }
            if (keptDire == 0) {
                return "Radiant";
            }
            senate = nextRound.toString();
        }
    }
}
